import type { IAsyncIterOptions } from './index';
import type { TAnySource, TElementOf } from './types';
/**
 * Normalize a source into an async iterable.
 * Accepts: async iterable, sync iterable, or a single promise.
 * Non-iterable values throw TypeError.
 */
export declare function from<T>(source: AsyncIterable<T>, opts?: IAsyncIterOptions): AsyncIterable<T>;
export declare function from<T>(source: Iterable<T | PromiseLike<T>>, opts?: IAsyncIterOptions): AsyncIterable<T>;
export declare function from<T>(source: PromiseLike<T>, opts?: IAsyncIterOptions): AsyncIterable<T>;
/**
 * Concatenate multiple sources, draining each in order.
 * Forward return() to the current active source.
 */
export declare function concat<TSources extends readonly TAnySource<any>[]>(...sources: TSources): AsyncIterable<TElementOf<TSources[number]>>;
export declare function concat<TSources extends readonly TAnySource<any>[]>(...sourcesAndOptions: [...TSources, IAsyncIterOptions]): AsyncIterable<TElementOf<TSources[number]>>;
/**
 * Zip multiple sources, pulling one value from each per round.
 * Yields tuples of values. Ends when the shortest source ends.
 * On early stop, calls return() on all sources (including losers).
 */
export declare function zip<TSources extends readonly TAnySource<any>[]>(...sources: TSources): AsyncIterable<{
    -readonly [K in keyof TSources]: TElementOf<TSources[K]>;
}>;
export declare function zip<TSources extends readonly TAnySource<any>[]>(...sourcesAndOptions: [...TSources, IAsyncIterOptions]): AsyncIterable<{
    -readonly [K in keyof TSources]: TElementOf<TSources[K]>;
}>;
/**
 * Zip multiple sources into objects, pulling one value from each per round.
 * Yields objects with the keys from the shape. Ends when the shortest source ends.
 * On early stop, calls return() on all sources.
 */
export declare function zipKeyed<T extends Record<string, TAnySource<any>>>(shape: T, _opts?: IAsyncIterOptions): AsyncIterable<{
    [K in keyof T]: TElementOf<T[K]>;
}>;
